# >>>GEN HNSCREEN_FILE_REVERSALS


def has_layer(src: str) -> bool:
    return MARKER in src


def peel(src: str) -> str:
    """undo the P6-HN-S edits (each `new` text must occur exactly once); a trainer without the layer is returned unchanged"""
    if not has_layer(src):
        return src
    for new, old in HNSCREEN_FILE_REVERSALS:
        assert src.count(new) == 1, f"P6-HN-S reversal: the text occurs {src.count(new)} times (must be exactly 1): {new[:70]!r}"
        src = src.replace(new, old)
    return src
